BEGIN
DELETE T_ECC_RES_ROLE_REL WHERE RES_ID = #{sp.resId} AND ROLE_ID = #{roleId}; INSERT INTO T_ECC_RES_ROLE_REL ( RES_ID, ROLE_ID, CREATE_ID, CREATE_TIME, MODIFY_ID, MODIFY_TIME )VALUES( #{sp.resId}, #{roleId}, #{sp.createId}, SYSDATE, #{sp.createId}, SYSDATE );
END;

BEGIN
INSERT INTO T_ECC_RES_ROLE_REL ( RES_ID, ROLE_ID, CREATE_ID, CREATE_TIME, MODIFY_ID, MODIFY_TIME )VALUES( #{resId}, #{sp.roleId}, #{sp.createId}, SYSDATE, #{sp.createId}, SYSDATE );
END;

mapper.select:
SELECT WRR.RES_ID, WRR.ROLE_ID, WRR.CREATE_ID, WRR.CREATE_TIME, WRR.MODIFY_ID, WRR.MODIFY_TIME FROM T_ECC_RES_ROLE_REL WRR WHERE 1=1
AND WRR.RES_ID = #{sp.resId}
AND WRR.ROLE_ID = #{sp.roleId}
